async function recoveredChatFixture(){
 const f=await fixture();f.conversation=randomUUID();await fs.writeFile(path.join(f.checkout,'résumé # notes.txt'),'RECOVERED CONTENT\n');
 f.oldReference=f.resolution.files.find(file=>file.path===f.checkout).id;
 const review=await f.maintenance.prepare(f.owner,f.run.id);await f.maintenance.commit(f.owner,review.id);f.review=review;f.restored=await f.maintenance.restore(f.owner,review.id);
 f.href=pathToFileURL(path.join(f.checkout,'résumé # notes.txt')).href;
 f.service=(offered=f.href,options={})=>{
  const db={from(table){const q={select(){return this;},eq(key,value){this[key]=value;return this;},order(){return this;},limit(){return this;},maybeSingle(){return this;},then(resolve,reject){return (async()=>{await options.query?.(table);const own=this.conversation_id===f.conversation&&(this.user_id===undefined||this.user_id===f.owner);return {error:null,data:table==='conversation_sessions'?own?{conversation_id:f.conversation}:null:table==='chat_messages_v2'&&own?[{content:{text:'[Recovered document](<'+offered+'>)'}}]:[]};})().then(resolve,reject);}};return q;}};
  // Construct fresh instances to prove the durable encrypted records, rather
  // than a retained in-memory translation, authorize this viewer-only route.
  const maintenance=new ScheduledWorkspaceMaintenance(f.secrets,new ScheduledWorkspaces(f.secrets,f.files,f.outputs,binary),f.recovery,f.host);
  return new ChatFiles(db,f.files,f.profile,path.join(f.root,'exports'),undefined,undefined,undefined,async(owner,args,guard)=>{const mapped=await maintenance.recoveredLink(owner,args,guard);return mapped?{...mapped,check:async()=>{await options.check?.();await mapped.check();}}:undefined;});
 };
 f.args=href=>({conversationId:f.conversation,href:href??f.href});return f;
}

