 await f.workspaces.restoreRepository(f.owner,f.run.id,restored,extracted,snapshot.git.head,true,noop,signal(),snapshot.git.policy);assert.equal(await f.git(['show',':draft.txt'],restored),'STAGED SNAPSHOT');assert.equal(await fs.readFile(path.join(restored,'draft.txt'),'utf8'),'DIRTY SNAPSHOT');assert.equal(await fs.readFile(path.join(restored,'.env'),'utf8'),'PRIVATE BACKUP ONLY');assert.deepEqual(f.secrets.values,before);assert.deepEqual(f.files.list(f.owner),references);
